"""Domain models for conversational assistant, chat messages, and tool definitions."""

from __future__ import annotations

from dataclasses import dataclass, field
import json
from typing import Any

from support.domain.schema import ReadOnlyDict


@dataclass(frozen=True)
class ToolCall:
    """Represents a structured tool invocation generated by a language model."""

    id: str
    name: str
    arguments: ReadOnlyDict

    def __init__(self, id: str, name: str, arguments: dict[str, Any] | ReadOnlyDict | None = None) -> None:
        object.__setattr__(self, "id", id or name)
        object.__setattr__(self, "name", name)
        object.__setattr__(
            self,
            "arguments",
            arguments if isinstance(arguments, ReadOnlyDict) else ReadOnlyDict(arguments or {}),
        )


@dataclass(frozen=True)
class ChatMessage:
    """Represents a single message in a multi-turn conversation."""

    role: str  # "system", "user", "assistant", "tool"
    content: str | None = None
    tool_calls: tuple[ToolCall, ...] = field(default_factory=tuple)
    tool_call_id: str | None = None
    name: str | None = None

    def to_dict(self) -> dict[str, Any]:
        """Convert chat message into an Ollama-compatible message dictionary."""
        d: dict[str, Any] = {"role": self.role}
        if self.content is not None:
            d["content"] = self.content
        else:
            d["content"] = ""

        if self.tool_calls:
            d["tool_calls"] = [
                {
                    "id": tc.id,
                    "type": "function",
                    "function": {
                        "name": tc.name,
                        "arguments": dict(tc.arguments),
                    },
                }
                for tc in self.tool_calls
            ]

        if self.tool_call_id is not None:
            d["tool_call_id"] = self.tool_call_id

        return d


@dataclass(frozen=True)
class ToolDefinition:
    """Represents a registered tool schema provided to a language model."""

    name: str
    description: str
    parameters: ReadOnlyDict

    def __init__(self, name: str, description: str, parameters: dict[str, Any] | None = None) -> None:
        object.__setattr__(self, "name", name)
        object.__setattr__(self, "description", description)
        object.__setattr__(
            self,
            "parameters",
            parameters if isinstance(parameters, ReadOnlyDict) else ReadOnlyDict(parameters or {"type": "object", "properties": {}}),
        )

    def to_dict(self) -> dict[str, Any]:
        """Convert tool definition into Ollama function specification."""
        return {
            "type": "function",
            "function": {
                "name": self.name,
                "description": self.description,
                "parameters": dict(self.parameters),
            },
        }


@dataclass(frozen=True)
class ModelInfo:
    """Information regarding a local model's availability and tool-calling capability."""

    name: str
    is_available: bool
    supports_tools: bool = True
    details: str | None = None
